<?php
use MSC\{TrainingCatalog,BulkPublication,ReleasePages,UpcomingReleases,Schema,Plugin,Queue,NetworkSites,Publication};
if(!defined('WP_CLI')||'local'!==wp_get_environment_type()||'1'!==getenv('MSC_DISPOSABLE_TESTS')){throw new RuntimeException('Explicit disposable local network required.');}
wp_set_current_user(1);$GLOBALS['tb_checks']=0;$store=Plugin::store();
function tb_check($ok,string$message):void{if(!$ok){throw new RuntimeException('FAIL: '.$message);}++$GLOBALS['tb_checks'];WP_CLI::log('PASS: '.$message);}
function tb_reject(callable$fn,string$message):void{try{$fn();}catch(Throwable$e){tb_check(true,$message);return;}throw new RuntimeException('FAIL: '.$message);}
function tb_drain():void{for($i=0;$i<300&&Queue::status()['pending'];++$i){$r=Queue::run(1000);if($r['errors']||!$r['processed']){throw new RuntimeException('Queue did not drain.');}}}
function tb_run(string$token):array{do{$job=BulkPublication::step($token);}while($job['index']<count($job['items']));return$job;}
$data=TrainingCatalog::dataset();$counts=array_count_values(array_column($data['items'],'type'));tb_check($counts['msc_movie']===250&&$counts['msc_show']===250&&count(array_unique(array_column($data['items'],'id')))===500,'The bundled dataset contains 250 distinct Movies and 250 distinct TV Shows');
$members=get_network_option(get_current_network_id(),'msc_training_catalog_records',array());
if(count($members)<500){$token=TrainingCatalog::start();do{$import=TrainingCatalog::step($token);}while($import['index']<500);$members=get_network_option(get_current_network_id(),'msc_training_catalog_records',array());}
tb_check(count($members)===500,'The complete 500-title catalog has been imported');tb_drain();
