$record=$movies[1];$row=array_values(array_filter($data['items'],static fn($r)=>$r['id']===$record['data']['external_ids']['wikidata']))[0];$before=count($store->query('msc_movie',array(),0,500));$again=TrainingCatalog::import_row($row);tb_check($again['uuid']===$record['uuid']&&$again['status']==='Reused existing record'&&$before===count($store->query('msc_movie',array(),0,500)),'Repeating an import reuses identities without creating extra Movies');
$edited=$store->update($record['id'],array('seo_description'=>'Keep this editorial description'),(int)$record['version']);TrainingCatalog::import_row($row);tb_check($store->get($record['id'])['data']['seo_description']==='Keep this editorial description','Reimports preserve editorial fields');
$movie=$movies[0];$a=$store->mapping((int)$movie['id'],$sites['a']);$b=$store->mapping((int)$movie['id'],$sites['b']);tb_check($a['status']==='draft'&&$b['status']==='draft','New training titles start as drafts on both participating sites');
$local=tb_run(BulkPublication::start(array((int)$a['post_id']),'site','msc_movie'));tb_check($local['results'][0]['status']==='Published'&&$store->mapping((int)$movie['id'],$sites['a'])['status']==='publish'&&$store->mapping((int)$movie['id'],$sites['b'])['status']==='draft','Local bulk publication affects only the selected site');
switch_to_blog($sites['b']);$m=$store->mapping((int)$movie['id']);$store->local($movie['id'],array('seo_description'=>'Local B override'),array(),(int)$m['local_version']);restore_current_blog();
$job=tb_run(BulkPublication::start(array((int)$a['post_id']),'global','msc_movie'));tb_check($store->mapping((int)$movie['id'],$sites['b'])['status']==='publish'&&$store->resolved($movie['id'],$sites['b'])['data']['seo_description']==='Local B override','Global publication reaches participating sites and preserves local field overrides');
$changed=$movies[2];$p=$store->mapping((int)$changed['id']);$token=BulkPublication::start(array((int)$p['post_id']),'global','msc_movie');$store->update($changed['id'],array('seo_description'=>'Concurrent global edit'),(int)$changed['version']);$job=tb_run($token);tb_check(str_starts_with($job['results'][0]['status'],'Skipped:')&&$store->mapping((int)$changed['id'])['status']==='draft','Records edited after selection are skipped for review');
$removed=$movies[3];switch_to_blog($sites['b']);$m=$store->mapping((int)$removed['id']);$store->local($removed['id'],array(),array(),(int)$m['local_version'],'removed');restore_current_blog();$m=$store->mapping((int)$removed['id']);tb_run(BulkPublication::start(array((int)$m['post_id']),'global','msc_movie'));tb_check((bool)$store->mapping((int)$removed['id'],$sites['b'])['suppressed'],'Global publication does not restore locally removed copies');
$tag=substr(wp_generate_uuid4(),0,6);$old=wp_insert_post(array('post_type'=>'page','post_status'=>'publish','post_title'=>'Legacy release guide '.$tag,'post_content'=>'<p>Keep the editorial introduction.</p>[msc_upcoming_releases month="2044-01"]','meta_input'=>array('_msc_release_page_key'=>'legacy-'.$tag)),true);delete_option('msc_release_posts_version');ReleasePages::upgrade();tb_check(get_post_type($old)==='post'&&get_post_status($old)==='pending'&&str_contains(get_post_field('post_content',$old),'Keep the editorial introduction.'),'Existing generated Pages become regular pending-review Posts without losing their content');
$native=wp_insert_post(array('post_type'=>'post','post_status'=>'pending','post_title'=>'Review publication '.$tag,'post_content'=>'<p>Editor reviewed this content.</p>'),true);$future=wp_insert_post(array('post_type'=>'post','post_status'=>'future','post_title'=>'Scheduled publication '.$tag,'post_date'=>wp_date('Y-m-d H:i:s',time()+DAY_IN_SECONDS),'post_date_gmt'=>gmdate('Y-m-d H:i:s',time()+DAY_IN_SECONDS)),true);
$native_job=tb_run(BulkPublication::start(array((int)$native,(int)$future),'site','post'));tb_check(get_post_status($native)==='publish'&&get_post_status($future)==='publish','Regular pending and scheduled Posts can be published immediately from bulk actions');
$generated=ReleasePages::generate('2044-02',1);$generated_id=$generated[0]['id'];tb_check(get_post_type($generated_id)==='post'&&(!$generated[0]['created']||get_post_status($generated_id)==='pending'),'New monthly guides are regular Posts queued for review');
tb_reject(static fn()=>BulkPublication::start(array((int)$native),'global','post'),'Regular Posts cannot request shared global publication');tb_reject(static fn()=>BulkPublication::start(array((int)$native,(int)$a['post_id']),'site','post'),'A bulk selection cannot mix unrelated post types');
$editor=wp_insert_user(array('user_login'=>'bulk-editor-'.$tag,'user_pass'=>wp_generate_password(32),'role'=>'editor'));wp_set_current_user($editor);tb_reject(static fn()=>BulkPublication::start(array((int)$a['post_id']),'global','msc_movie'),'Editors without network permission cannot publish globally');tb_reject(static fn()=>TrainingCatalog::start(),'Editors cannot start a network training import');tb_reject(static fn()=>BulkPublication::job($token),'Publication jobs cannot be read by another user');wp_set_current_user(1);
$all_ids=array_map(static fn($r)=>(int)$store->mapping((int)$r['id'])['post_id'],$movies);$mass=tb_run(BulkPublication::start($all_ids,'global','msc_movie'));tb_check($mass['index']===250&&count(array_filter($mass['results'],static fn($r)=>$r['status']==='Published'))===250,'A full 250-Movie selection publishes successfully in resumable batches');
$info=array('movies'=>admin_url('edit.php?post_type=msc_movie&msc_training=1'),'training'=>admin_url('admin.php?page=msc-training'),'release_admin'=>admin_url('admin.php?page=msc-release-pages'),'posts'=>admin_url('edit.php'),'pending_id'=>$generated_id,'pending_url'=>get_permalink($generated_id),'bulk_ids'=>array((int)$store->mapping((int)$shows[0]['id'])['post_id'],(int)$store->mapping((int)$shows[1]['id'])['post_id']),'shows'=>admin_url('edit.php?post_type=msc_show&msc_training=1'));
restore_current_blog();echo 'TRAINING_BROWSER_JSON:'.wp_json_encode($info)."\n";WP_CLI::success($GLOBALS['tb_checks'].' training, mass publication and release-review workflow checks passed.');
